const STUDIO="<!DOCTYPE html>\n<html lang=\"ru\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, maximum-scale=1, user-scalable=no, viewport-fit=cover\">\n<title>AI Студия</title>\n<script src=\"https://telegram.org/js/telegram-web-app.js\"></script>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\"><link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin><link href=\"https://fonts.googleapis.com/css2?family=Onest:wght@400;500;600;700;800&family=Unbounded:wght@600;700;800&display=swap\" rel=\"stylesheet\">\n<style>\n:root{--bg:var(--tg-theme-secondary-bg-color,#f2f3f7);--card:var(--tg-theme-bg-color,#fff);--tx:var(--tg-theme-text-color,#0f1222);--hint:var(--tg-theme-hint-color,#8a90a2);\n--soft:color-mix(in srgb,var(--hint) 12%,transparent);--hair:color-mix(in srgb,var(--hint) 16%,transparent);--bad:#e5484d;--ok:#16a34a;\n--display:\"Unbounded\",\"Onest\",-apple-system,sans-serif;\n--ai:radial-gradient(120% 90% at 100% 0%,rgba(255,255,255,.22),transparent 55%),linear-gradient(140deg,#0b8f87 0%,#2f5bd8 50%,#7b2fe0 100%);--acc:#2f5bd8}\n*{box-sizing:border-box;-webkit-tap-highlight-color:transparent}\nhtml,body{background:var(--bg);margin:0}\nbody{color:var(--tx);font:15px/1.45 \"Onest\",-apple-system,BlinkMacSystemFont,\"Segoe UI\",Roboto,sans-serif;-webkit-font-smoothing:antialiased;padding-bottom:40px;letter-spacing:-.006em}\nbody.fs{padding-top:var(--fs-top,0px)}\nbutton,input,textarea{font:inherit;color:inherit}\nbutton{border:0;background:none;cursor:pointer;padding:0}\n:focus-visible{outline:2px solid var(--acc);outline-offset:2px}\n.hero{background:var(--ai);color:#fff;padding:22px 20px 56px;border-radius:0 0 30px 30px}\n.hero h1{margin:0;font-family:var(--display);font-weight:700;font-size:22px;letter-spacing:-.035em}\n.hero p{margin:4px 0 0;opacity:.88;font-size:13.5px}\n.bud{margin-top:16px;background:rgba(255,255,255,.16);box-shadow:inset 0 0 0 1px rgba(255,255,255,.22);border-radius:16px;padding:11px 13px;display:flex;align-items:center;gap:12px}\n.bud .bar{flex:1;height:7px;border-radius:5px;background:rgba(255,255,255,.25);overflow:hidden}.bud .bar i{display:block;height:100%;background:#fff;border-radius:5px;transition:width .4s}\n.bud b{font-family:var(--display);font-weight:600;font-size:13px;white-space:nowrap}\n.bud button{font-size:12.5px;font-weight:700;opacity:.9;text-decoration:underline;text-underline-offset:3px}\n.wrap{max-width:640px;margin:-40px auto 0;padding:0 14px;position:relative}\n.card{background:var(--card);border-radius:22px;padding:16px;margin-top:12px;box-shadow:0 0 0 1px var(--hair),0 8px 24px -12px rgba(24,28,70,.18)}\n.ttl{font-weight:700;font-size:15px;margin:0 0 10px;display:flex;align-items:center;gap:8px}.ttl small{margin-left:auto;color:var(--hint);font-weight:600;font-size:12px}\n.seg{display:grid;grid-template-columns:1fr 1fr;background:var(--soft);border-radius:15px;padding:4px}\n.seg button{padding:11px 4px;border-radius:12px;font-weight:700;color:var(--hint)}.seg button.on{background:var(--card);color:var(--tx);box-shadow:0 2px 8px rgba(0,0,0,.08)}\ntextarea{width:100%;min-height:96px;border:0;border-radius:16px;background:var(--soft);padding:12px 14px;resize:vertical;outline:none;line-height:1.45}\n.chips{display:flex;gap:6px;overflow-x:auto;scrollbar-width:none;margin-top:10px;padding-bottom:2px}.chips::-webkit-scrollbar{display:none}\n.chips button{flex:none;padding:8px 11px;border-radius:12px;background:var(--soft);font-weight:600;font-size:13px;white-space:nowrap}\n.photo{display:flex;align-items:center;gap:12px;margin-top:12px;padding:10px;border-radius:16px;border:1.5px dashed var(--hair);cursor:pointer}\n.photo .th{width:56px;height:56px;border-radius:12px;background:var(--soft) center/cover;flex:none;display:grid;place-items:center;font-size:22px}\n.photo b{display:block;font-size:14px}.photo span{color:var(--hint);font-size:12.5px}\n.photo .x{margin-left:auto;width:30px;height:30px;border-radius:10px;background:var(--soft);color:var(--bad);font-weight:800}\n.row{display:flex;gap:8px;margin-top:12px}\n.pill{flex:1;padding:10px 6px;border-radius:13px;background:var(--soft);font-weight:700;font-size:13.5px;text-align:center}\n.pill.on{background:color-mix(in srgb,var(--acc) 14%,transparent);color:var(--acc);box-shadow:inset 0 0 0 1.5px var(--acc)}\n.q{display:grid;gap:8px;margin-top:12px}\n.qo{display:flex;align-items:center;gap:12px;padding:12px 14px;border-radius:16px;background:var(--soft);text-align:left}\n.qo.on{background:color-mix(in srgb,var(--acc) 12%,transparent);box-shadow:inset 0 0 0 1.5px var(--acc)}\n.qo b{display:block}.qo span{color:var(--hint);font-size:12.5px}\n.qo .pr{margin-left:auto;font-family:var(--display);font-weight:600;font-size:14px;letter-spacing:-.02em}\n.go{width:100%;margin-top:14px;padding:16px;border-radius:18px;background:var(--ai);color:#fff;font-weight:800;font-size:16px;box-shadow:0 14px 30px -12px rgba(47,91,216,.6)}\n.go:disabled{opacity:.55}\n.err{color:var(--bad);font-size:13.5px;margin-top:8px}\n.grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}\n.it{border-radius:16px;overflow:hidden;background:var(--soft);position:relative}\n.it .media{aspect-ratio:9/16;background:#000 center/cover;display:block;width:100%;object-fit:cover}\n.it .media.h{aspect-ratio:16/9}.it .media.s{aspect-ratio:1}\n.it .wait{aspect-ratio:9/16;display:grid;place-items:center;text-align:center;padding:10px;color:var(--hint);font-size:12.5px;background:linear-gradient(110deg,var(--soft) 30%,color-mix(in srgb,var(--acc) 10%,transparent) 50%,var(--soft) 70%);background-size:300% 100%;animation:sh 1.6s linear infinite}\n@keyframes sh{to{background-position:-150% 0}}\n.it .bd{padding:8px 10px 10px}\n.it .p{font-size:12.5px;line-height:1.35;overflow:hidden;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical}\n.it .m{font-size:11.5px;color:var(--hint);margin-top:3px}\n.it .ac{display:flex;gap:5px;margin-top:7px}.it .ac button{flex:1;padding:7px 4px;border-radius:10px;background:var(--card);font-weight:700;font-size:12px}\n.it .er{color:var(--bad);font-size:12px;margin-top:4px}\n.empty{color:var(--hint);text-align:center;padding:18px 8px;font-size:14px}\n@media (prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}\n</style>\n</head>\n<body>\n<div class=\"hero\">\n  <h1>AI Студия</h1>\n  <p>Видео и картинки нейросетью — сразу в Reels и посты</p>\n  <div class=\"bud\"><div class=\"bar\"><i id=\"budBar\" style=\"width:0\"></i></div><b id=\"budTxt\">$0 из $15</b><button id=\"budEdit\">лимит</button></div>\n</div>\n<div class=\"wrap\">\n  <div class=\"card\">\n    <div class=\"seg\" id=\"mode\"><button data-v=\"video\" class=\"on\">🎬 Видео</button><button data-v=\"image\">🖼 Картинка</button></div>\n    <div class=\"photo\" id=\"photoBox\"><div class=\"th\" id=\"pTh\">📷</div><div><b id=\"pT\">Добавить фото</b><span id=\"pS\">Необязательно — оживлю его в видео</span></div><button class=\"x\" id=\"pX\" style=\"display:none\" aria-label=\"Убрать фото\">✕</button></div>\n    <input type=\"file\" id=\"pIn\" accept=\"image/*\" hidden>\n    <div style=\"margin-top:12px\"><textarea id=\"prompt\" placeholder=\"Опиши, что должно быть в кадре — можно по-русски или по-узбекски\"></textarea></div>\n    <div class=\"chips\" id=\"tpl\"></div>\n    <div class=\"row\" id=\"asp\"></div>\n    <div class=\"q\" id=\"qual\"></div>\n    <button class=\"go\" id=\"go\">Создать</button>\n    <div class=\"err\" id=\"err\"></div>\n  </div>\n  <div class=\"card\"><div class=\"ttl\">Мои генерации<small id=\"cnt\"></small></div><div id=\"list\"></div></div>\n</div>\n<script>\nconst tg = window.Telegram?.WebApp;\ntg?.ready(); tg?.expand();\n(function fullscreen() {\n  if (!tg) return;\n  const top = () => (tg.safeAreaInset?.top || 0) + (tg.contentSafeAreaInset?.top || 0);\n  const apply = () => { document.documentElement.style.setProperty(\"--fs-top\", (tg.isFullscreen ? top() : 0) + \"px\"); document.body.classList.toggle(\"fs\", !!tg.isFullscreen); };\n  try { tg.onEvent?.(\"fullscreenChanged\", apply); tg.onEvent?.(\"safeAreaChanged\", apply); tg.onEvent?.(\"contentSafeAreaChanged\", apply);\n    if ([\"ios\", \"android\"].includes(tg.platform) && tg.isVersionAtLeast?.(\"8.0\") && !tg.isFullscreen) tg.requestFullscreen(); tg.disableVerticalSwipes?.(); } catch (e) {}\n  apply();\n})();\ntry { tg?.setHeaderColor?.(\"secondary_bg_color\"); tg?.setBackgroundColor?.(\"secondary_bg_color\"); tg?.BackButton?.show(); tg?.BackButton?.onClick(() => { location.href = \"/app\"; }); } catch (e) {}\nconst $ = (id) => document.getElementById(id);\nconst esc = (s) => String(s ?? \"\").replace(/[&<>\"']/g, (c) => ({ \"&\": \"&amp;\", \"<\": \"&lt;\", \">\": \"&gt;\", '\"': \"&quot;\", \"'\": \"&#39;\" })[c]);\nconst hap = (t) => { try { t === \"ok\" ? tg?.HapticFeedback?.notificationOccurred(\"success\") : t === \"err\" ? tg?.HapticFeedback?.notificationOccurred(\"error\") : tg?.HapticFeedback?.selectionChanged(); } catch (e) {} };\nasync function api(method, path, body) {\n  const r = await fetch(path, { method, headers: { \"x-init-data\": tg?.initData || \"\", \"content-type\": \"application/json\" }, body: body ? JSON.stringify(body) : undefined });\n  const j = await r.json().catch(() => ({}));\n  if (!r.ok) throw new Error(j.error || \"Ошибка \" + r.status);\n  return j;\n}\nconst TPL = {\n  video: [[\"🏠 Дом на рассвете\", \"Современный каркасный дом в сосновом лесу на рассвете, туман, камера медленно облетает дом\"], [\"📦 Реклама товара\", \"Товар вращается на подиуме, мягкий студийный свет, крупные планы деталей, динамичная музыка\"], [\"🛋 Интерьер оживает\", \"Пустая комната за несколько секунд наполняется стильной мебелью, тёплый свет\"], [\"🍲 Еда крупным планом\", \"Плов в казане крупным планом, пар поднимается, замедленная съёмка\"], [\"🎤 Говорящая голова\", \"Уверенный предприниматель в офисе смотрит в камеру и говорит: «Хотите узнать секрет?»\"]],\n  image: [[\"🖼 Обложка Reels\", \"Яркая обложка для Reels в стиле бизнес-блога, крупный план человека с удивлённым лицом, много свободного места сверху под заголовок\"], [\"🏠 Дом мечты\", \"Фотореалистичный каркасный дом с панорамными окнами, вечер, тёплый свет из окон\"], [\"📦 Товар на фоне\", \"Товар на минималистичном пастельном фоне, студийный свет, премиальная съёмка\"], [\"🎨 Иллюстрация\", \"Плоская иллюстрация в стиле Notion: команда работает над проектом\"]],\n};\nlet mode = \"video\", aspect = \"9:16\", quality = \"eco\", photo = null, prices = { video: { eco: 0.4, std: 0.8, max: 3.2 }, image: { eco: 0.04, max: 0.14 } }, busy = false, data = null, timer = null;\nfunction renderOpts() {\n  $(\"mode\").querySelectorAll(\"button\").forEach((b) => b.classList.toggle(\"on\", b.dataset.v === mode));\n  $(\"tpl\").innerHTML = TPL[mode].map(([n, p], i) => `<button data-i=\"${i}\">${esc(n)}</button>`).join(\"\");\n  $(\"tpl\").querySelectorAll(\"button\").forEach((b) => (b.onclick = () => { $(\"prompt\").value = TPL[mode][+b.dataset.i][1]; hap(); }));\n  const asps = mode === \"image\" ? [[\"9:16\", \"Вертикально\"], [\"1:1\", \"Квадрат\"], [\"16:9\", \"Горизонт.\"]] : [[\"9:16\", \"Вертикально 9:16\"], [\"16:9\", \"Горизонт. 16:9\"]];\n  if (!asps.some(([a]) => a === aspect)) aspect = \"9:16\";\n  $(\"asp\").innerHTML = asps.map(([a, n]) => `<button class=\"pill${a === aspect ? \" on\" : \"\"}\" data-a=\"${a}\">${n}</button>`).join(\"\");\n  $(\"asp\").querySelectorAll(\"button\").forEach((b) => (b.onclick = () => { aspect = b.dataset.a; hap(); renderOpts(); }));\n  const qs = mode === \"image\" ? [[\"eco\", \"Быстро\", \"хорошо для обложек и черновиков\"], [\"max\", \"Максимум\", \"лучшая детализация и текст\"]] : [[\"eco\", \"Эконом\", \"720p, 8 сек — для проб\"], [\"std\", \"Стандарт\", \"720p, лучше движение\"], [\"max\", \"Максимум\", \"1080p, кино-качество\"]];\n  if (!qs.some(([q]) => q === quality)) quality = \"eco\";\n  $(\"qual\").innerHTML = qs.map(([q, n, d]) => `<button class=\"qo${q === quality ? \" on\" : \"\"}\" data-q=\"${q}\"><div><b>${n}</b><span>${d}</span></div><div class=\"pr\">≈$${(prices[mode][q] ?? 0).toFixed(2)}</div></button>`).join(\"\");\n  $(\"qual\").querySelectorAll(\"button\").forEach((b) => (b.onclick = () => { quality = b.dataset.q; hap(); renderOpts(); }));\n  $(\"pS\").textContent = mode === \"image\" ? \"Необязательно — изменю это фото по описанию\" : \"Необязательно — оживлю его в видео\";\n  $(\"go\").textContent = `${mode === \"image\" ? \"Нарисовать\" : photo ? \"Оживить фото\" : \"Создать видео\"} · ≈$${(prices[mode][quality] ?? 0).toFixed(2)}`;\n}\n$(\"mode\").querySelectorAll(\"button\").forEach((b) => (b.onclick = () => { mode = b.dataset.v; hap(); renderOpts(); }));\n$(\"photoBox\").onclick = (e) => { if (e.target.id !== \"pX\") $(\"pIn\").click(); };\n$(\"pX\").onclick = (e) => { e.stopPropagation(); photo = null; $(\"pTh\").style.backgroundImage = \"\"; $(\"pTh\").textContent = \"📷\"; $(\"pT\").textContent = \"Добавить фото\"; $(\"pX\").style.display = \"none\"; renderOpts(); };\n$(\"pIn\").onchange = async () => {\n  const f = $(\"pIn\").files[0]; if (!f) return;\n  const img = await createImageBitmap(f).catch(() => null);\n  if (!img) { $(\"err\").textContent = \"Не получилось открыть фото\"; return; }\n  const k = Math.min(1, 1280 / Math.max(img.width, img.height));\n  const c = document.createElement(\"canvas\"); c.width = Math.round(img.width * k); c.height = Math.round(img.height * k);\n  c.getContext(\"2d\").drawImage(img, 0, 0, c.width, c.height);\n  const url = c.toDataURL(\"image/jpeg\", 0.88);\n  photo = url.split(\",\")[1];\n  $(\"pTh\").style.backgroundImage = `url('${url}')`; $(\"pTh\").textContent = \"\"; $(\"pT\").textContent = \"Фото добавлено\"; $(\"pX\").style.display = \"\";\n  $(\"pIn\").value = \"\"; renderOpts();\n};\n$(\"go\").onclick = async () => {\n  if (busy) return;\n  const prompt = $(\"prompt\").value.trim();\n  if (!prompt && !photo) { $(\"err\").textContent = \"Опиши, что сгенерировать, или добавь фото\"; hap(\"err\"); return; }\n  busy = true; $(\"go\").disabled = true; $(\"err\").textContent = \"\"; $(\"go\").textContent = mode === \"image\" ? \"Рисую… ~20 сек\" : \"Запускаю…\";\n  try {\n    await api(\"POST\", \"/api/gen\", { type: mode, prompt, quality, aspect, imageB64: photo, imageMime: \"image/jpeg\" });\n    hap(\"ok\"); $(\"prompt\").value = \"\"; await load();\n  } catch (e) { $(\"err\").textContent = \"⚠️ \" + e.message; hap(\"err\"); }\n  busy = false; $(\"go\").disabled = false; renderOpts();\n};\n$(\"budEdit\").onclick = async () => {\n  const cur = data?.limit || 15;\n  const v = prompt(\"Лимит расходов на AI-генерацию в месяц, $\", String(cur));\n  if (!v) return;\n  try { await api(\"POST\", \"/api/gen/limit\", { limit: Number(v.replace(\",\", \".\")) }); load(); } catch (e) {}\n};\nfunction ago(s) {\n  const d = (Date.now() - new Date(s.replace(\" \", \"T\") + \"Z\")) / 60000;\n  return d < 1 ? \"только что\" : d < 60 ? Math.round(d) + \" мин назад\" : d < 1440 ? Math.round(d / 60) + \" ч назад\" : new Date(s.replace(\" \", \"T\") + \"Z\").toLocaleDateString(\"ru-RU\", { day: \"numeric\", month: \"short\" });\n}\nfunction render() {\n  const b = data;\n  $(\"budBar\").style.width = Math.min(100, (b.spent / b.limit) * 100) + \"%\";\n  $(\"budTxt\").textContent = `$${b.spent.toFixed(2)} из $${b.limit}`;\n  $(\"cnt\").textContent = b.items.length ? b.items.length : \"\";\n  $(\"list\").innerHTML = b.items.length ? `<div class=\"grid\">${b.items.map((g) => {\n    const cls = g.aspect === \"16:9\" ? \" h\" : g.aspect === \"1:1\" ? \" s\" : \"\";\n    const src = `/gen/${g.id}/${g.token}.${g.type === \"image\" ? \"png\" : \"mp4\"}`;\n    const media = g.status === \"done\" ? (g.type === \"image\" ? `<img class=\"media${cls}\" src=\"${src}\" alt=\"\">` : `<video class=\"media${cls}\" src=\"${src}#t=0.3\" preload=\"metadata\" playsinline loop muted></video>`)\n      : g.status === \"error\" ? `<div class=\"wait\" style=\"animation:none\">⚠️</div>` : `<div class=\"wait\">${g.type === \"image\" ? \"Рисую…\" : \"Генерирую видео…<br>1–3 минуты\"}</div>`;\n    return `<div class=\"it\">${media}<div class=\"bd\"><div class=\"p\">${esc(g.prompt)}</div><div class=\"m\">${g.type === \"image\" ? \"🖼\" : \"🎬\"} ${ago(g.created_at)} · $${g.cost}</div>\n      ${g.status === \"error\" ? `<div class=\"er\">${esc(g.error || \"ошибка\")}</div>` : \"\"}\n      ${g.status === \"done\" ? `<div class=\"ac\">${g.type === \"video\" ? `<button data-reel=\"${g.id}\">📱 В Reels</button>` : \"\"}<button data-open=\"${src}\">⬇️ Открыть</button></div>` : \"\"}</div></div>`;\n  }).join(\"\")}</div>` : `<div class=\"empty\">Здесь появятся твои видео и картинки. Начни с шаблона выше.</div>`;\n  $(\"list\").querySelectorAll(\"video\").forEach((v) => (v.onclick = () => { v.muted = false; v.paused ? v.play() : v.pause(); }));\n  $(\"list\").querySelectorAll(\"[data-open]\").forEach((x) => (x.onclick = () => { const u = location.origin + x.dataset.open; tg?.openLink ? tg.openLink(u) : window.open(u); }));\n  $(\"list\").querySelectorAll(\"[data-reel]\").forEach((x) => (x.onclick = async () => {\n    x.disabled = true; x.textContent = \"…\";\n    try { await api(\"POST\", `/api/gen/${x.dataset.reel}/reel`); x.textContent = \"✓ Черновик в чате\"; hap(\"ok\"); }\n    catch (e) { x.textContent = \"⚠️\"; x.disabled = false; }\n  }));\n  clearTimeout(timer);\n  if (b.items.some((g) => g.status === \"running\" || g.status === \"starting\")) timer = setTimeout(load, 8000);\n}\nasync function load() {\n  try { data = await api(\"GET\", \"/api/gen\"); if (data.prices) prices = data.prices; render(); renderOpts(); }\n  catch (e) { $(\"list\").innerHTML = `<div class=\"empty\">⚠️ ${esc(e.message)}</div>`; }\n}\nrenderOpts(); load();\n</script>\n</body>\n</html>\n";
const sha=async t=>[...new Uint8Array(await crypto.subtle.digest("SHA-256",new TextEncoder().encode(t)))].map(b=>b.toString(16).padStart(2,"0")).join("");
