const meta={main_module:name,bindings:binds.filter(b=>!["secret_text","secret_key"].includes(b.type)),keep_bindings:["secret_text","secret_key"],compatibility_date:st.result.compatibility_date,compatibility_flags:st.result.compatibility_flags};
const form=new FormData(); form.append("metadata",new Blob([JSON.stringify(meta)],{type:"application/json"})); form.append(name,new Blob([ns],{type:"application/javascript+module"}),name);
